const fs = require('fs');
const path = require('path');
const dir = __dirname;

function template(title, subtitle, questions) {
  const q = JSON.stringify(questions);
  return `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: #1a1a2e; color: #e0e0e0; min-height: 100vh; padding: 2rem 1rem; }
    .container { max-width: 800px; margin: 0 auto; }
    h1 { text-align: center; margin-bottom: 0.5rem; font-size: 1.8rem; color: #ffffff; }
    .subtitle { text-align: center; color: #8892b0; margin-bottom: 2rem; font-size: 1rem; }
    .progress-bar-container { background: #0d1117; border-radius: 10px; height: 14px; margin-bottom: 2rem; overflow: hidden; }
    .progress-bar { background: linear-gradient(90deg, #0d6efd, #4dabf7); height: 100%; width: 0%; border-radius: 10px; transition: width 0.4s ease; }
    .progress-text { text-align: center; color: #8892b0; margin-bottom: 1rem; font-size: 0.9rem; }
    .card { background: #16213e; border-radius: 12px; padding: 2rem; margin-bottom: 1.5rem; box-shadow: 0 4px 20px rgba(0,0,0,0.3); }
    .question-label { font-size: 0.85rem; color: #4dabf7; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 0.5rem; }
    .question-text { font-size: 1.15rem; margin-bottom: 1.2rem; line-height: 1.5; color: #ffffff; }
    pre { background: #0d1117; border: 1px solid #30363d; border-radius: 8px; padding: 1rem; margin-bottom: 1.2rem; overflow-x: auto; font-size: 0.95rem; }
    code { font-family: 'Consolas', 'Fira Code', 'Courier New', monospace; color: #c9d1d9; }
    .options { list-style: none; }
    .options li { margin-bottom: 0.5rem; }
    .options label { display: flex; align-items: center; gap: 0.75rem; padding: 0.8rem 1rem; background: #0d1117; border: 2px solid #30363d; border-radius: 8px; cursor: pointer; transition: border-color 0.2s, background 0.2s; font-size: 1rem; }
    .options label:hover { border-color: #4dabf7; background: #1c2a4a; }
    .options input[type="radio"] { accent-color: #0d6efd; width: 18px; height: 18px; flex-shrink: 0; }
    .btn { display: inline-block; padding: 0.7rem 2rem; border: none; border-radius: 8px; font-size: 1rem; font-weight: 600; cursor: pointer; transition: background 0.2s, transform 0.1s; }
    .btn-primary { background: #0d6efd; color: #fff; }
    .btn-primary:hover { background: #3b82f6; }
    .btn-primary:disabled { background: #374151; cursor: not-allowed; }
    .btn-restart { background: #238636; color: #fff; margin-top: 1rem; padding: 0.7rem 2rem; border: none; border-radius: 8px; font-size: 1rem; font-weight: 600; cursor: pointer; }
    .btn-restart:hover { background: #2ea043; }
    .feedback { margin-top: 1rem; padding: 1rem 1.2rem; border-radius: 8px; font-size: 0.95rem; line-height: 1.5; display: none; }
    .feedback.correct { background: #0f5132; border: 1px solid #198754; color: #d1fae5; display: block; }
    .feedback.wrong { background: #842029; border: 1px solid #dc3545; color: #fdd; display: block; }
    .score-card { text-align: center; padding: 3rem 2rem; }
    .score-card .score { font-size: 3rem; font-weight: 700; color: #4dabf7; margin-bottom: 0.5rem; }
    .score-card .score-label { font-size: 1.2rem; color: #8892b0; margin-bottom: 1.5rem; }
    .hidden { display: none; }
  </style>
</head>
<body>
  <div class="container">
    <h1>${title}</h1>
    <p class="subtitle">${subtitle}</p>
    <div class="progress-bar-container"><div class="progress-bar" id="progressBar"></div></div>
    <p class="progress-text" id="progressText">Question 1 / 5</p>
    <div id="quizContainer"></div>
    <div id="scoreContainer" class="card score-card hidden"></div>
  </div>
  <script>
    const questions = ${q};
    let currentQuestion = 0, score = 0, answered = false;
    function renderQuestion() { const q = questions[currentQuestion]; const total = questions.length; document.getElementById('progressBar').style.width = ((currentQuestion / total) * 100) + '%'; document.getElementById('progressText').textContent = \`Question \${currentQuestion + 1} / \${total}\`; let html = \`<div class="card"><p class="question-label">\${q.label}</p><p class="question-text">\${q.text}</p>\`; if (q.code) html += \`<pre><code>\${q.code}</code></pre>\`; html += \`<ul class="options">\`; q.options.forEach((opt, i) => { html += \`<li><label><input type="radio" name="q" value="\${i}"> \${opt}</label></li>\`; }); html += \`</ul><button class="btn btn-primary" id="validateBtn" onclick="validate()" disabled>Valider</button><div class="feedback" id="feedback"></div></div>\`; document.getElementById('quizContainer').innerHTML = html; document.querySelectorAll('input[name="q"]').forEach(r => { r.addEventListener('change', () => { document.getElementById('validateBtn').disabled = false; }); }); answered = false; }
    function validate() { if (answered) { currentQuestion++; if (currentQuestion < questions.length) renderQuestion(); else showScore(); return; } answered = true; const selected = document.querySelector('input[name="q"]:checked'); if (!selected) return; const val = parseInt(selected.value), q = questions[currentQuestion]; const fb = document.getElementById('feedback'), btn = document.getElementById('validateBtn'); document.querySelectorAll('input[name="q"]').forEach(r => r.disabled = true); if (val === q.answer) { score++; fb.className = 'feedback correct'; fb.innerHTML = \`<strong>Correct !</strong> \${q.explanation}\`; } else { fb.className = 'feedback wrong'; fb.innerHTML = \`<strong>Incorrect.</strong> \${q.explanation}\`; } btn.textContent = currentQuestion < questions.length - 1 ? 'Suivant' : 'Voir le score'; }
    function showScore() { document.getElementById('quizContainer').classList.add('hidden'); document.getElementById('progressBar').style.width = '100%'; document.getElementById('progressText').textContent = 'Termine !'; const sc = document.getElementById('scoreContainer'); sc.classList.remove('hidden'); const pct = Math.round((score / questions.length) * 100); let msg = pct === 100 ? 'Parfait !' : pct >= 60 ? 'Bien joue !' : 'Continuez a reviser !'; sc.innerHTML = \`<div class="score">\${score} / \${questions.length}</div><div class="score-label">\${msg} (\${pct}%)</div><button class="btn-restart" onclick="restart()">Recommencer</button>\`; }
    function restart() { currentQuestion = 0; score = 0; answered = false; document.getElementById('scoreContainer').classList.add('hidden'); document.getElementById('quizContainer').classList.remove('hidden'); renderQuestion(); }
    renderQuestion();
  </script>
</body>
</html>`;
}

const quizzes = [
  // ===== 08 — Securite =====
  { file: "quiz-08-01-owasp-stride.html", title: "Quiz — OWASP Top 10 & STRIDE", subtitle: "Module 08 — Securite (Cours 56)", questions: [
    { label: "IDOR", text: "Pourquoi les UUIDs v4 ne suffisent-ils pas a proteger contre les IDOR ?", options: ["Les UUIDs sont trop longs pour les URLs", "Un attaquant peut obtenir un UUID par d'autres moyens — il faut toujours verifier l'ownership cote serveur", "Les UUIDs ne sont pas supportes par les navigateurs", "Les UUIDs ralentissent les index B-tree"], answer: 1, explanation: "Les UUIDs empechent la devination (122 bits d'entropie), mais un attaquant peut obtenir un UUID par d'autres canaux (logs, referrer). Il faut toujours verifier l'ownership cote serveur en plus." },
    { label: "Injection SQL", text: "Quelle est la meilleure protection contre l'injection SQL ?", options: ["Echapper les caracteres speciaux avec une regex", "Utiliser des requetes parametrees ($1, $2) ou le driver traite les valeurs, jamais comme du SQL", "Limiter la longueur des champs de saisie", "Utiliser un WAF"], answer: 1, explanation: "Les requetes parametrees separent le code SQL des valeurs. Le driver traite $1 comme une VALEUR, jamais du SQL executable. C'est la seule protection fiable." },
    { label: "STRIDE", text: "Que signifie le 'E' dans STRIDE ?", options: ["Encryption", "Error handling", "Elevation of Privilege — un utilisateur obtient des droits superieurs aux siens", "Exposure"], answer: 2, explanation: "STRIDE : Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, Elevation of Privilege. La parade est le RBAC avec le principe du moindre privilege." },
    { label: "XSS", text: "Pourquoi la double sanitization (serveur + client) est-elle necessaire contre le XSS ?", options: ["Pour des raisons de performance", "DOMPurify protege a l'ecriture, React auto-escape a la lecture, et la CSP est le filet final", "Une seule couche ne fonctionne pas", "Pour respecter la norme OWASP"], answer: 1, explanation: "La sanitization serveur supprime les balises dangereuses AVANT stockage. L'echappement client protege au rendu. La CSP bloque les scripts inline restants. Defense en profondeur." },
    { label: "Trust Boundary", text: "Qu'est-ce qu'une trust boundary dans un Data Flow Diagram ?", options: ["La limite de stockage de la DB", "Un point ou le niveau de confiance change et ou les donnees doivent etre inspectees", "La frontiere entre deux microservices du meme domaine", "Le seuil de rate limiting"], answer: 1, explanation: "Chaque traversee de trust boundary est un point d'inspection : Internet vers DMZ (WAF), DMZ vers reseau interne (VPC). On applique les controles STRIDE a chaque frontiere." }
  ]},
  { file: "quiz-08-02-zero-trust.html", title: "Quiz — Architecture Zero Trust", subtitle: "Module 08 — Securite (Cours 57)", questions: [
    { label: "Principe fondamental", text: "Quel principe distingue le Zero Trust de la securite perimetrique ?", options: ["Utiliser des firewalls plus puissants", "Ne faire confiance a rien par defaut, meme en interne — chaque requete est authentifiee, autorisee et chiffree", "Centraliser la securite dans un seul service", "Dupliquer les donnees pour la resilience"], answer: 1, explanation: "La securite perimetrique fait confiance au reseau interne. Le Zero Trust verifie chaque appel : authentification (JWT), autorisation (RBAC), chiffrement (mTLS), meme entre services internes." },
    { label: "mTLS", text: "Pourquoi le mTLS est-il prefere au TLS classique entre services ?", options: ["Le mTLS est plus rapide", "Le mTLS authentifie les DEUX parties, empechant un attaquant dans le reseau d'usurper un service", "Le mTLS ne necessite pas de certificats", "Le mTLS chiffre mieux les donnees"], answer: 1, explanation: "Le TLS classique n'authentifie que le serveur. Avec mTLS, le client prouve aussi son identite via un certificat. Un attaquant dans le reseau ne peut pas usurper un service sans son certificat." },
    { label: "Default-deny", text: "Que signifie 'default-deny' dans une NetworkPolicy Kubernetes ?", options: ["Tous les pods sont supprimes", "Tout le trafic est bloque par defaut — seules les communications explicitement autorisees passent", "Les pods ne demarrent pas", "Les logs sont desactives"], answer: 1, explanation: "En default-deny, un pod ne peut rien envoyer ni recevoir. On ajoute des exceptions explicites. Si un service est compromis, l'attaquant ne peut pas se deplacer lateralement." },
    { label: "Identity-based", text: "Pourquoi preferer l'identity-based access a l'IP-based access ?", options: ["Les IPs sont plus dures a configurer", "Les IPs changent constamment (auto-scaling, containers), l'identite (certificat, JWT) reste stable", "L'identity-based est moins cher", "Les IPs ne sont pas supportees dans le cloud"], answer: 1, explanation: "Dans un environnement cloud avec auto-scaling, les IPs changent constamment. L'identite du service (certificat, SPIFFE ID) est stable et portable." },
    { label: "Assume breach", text: "Quel pilier Zero Trust consiste a architecturer comme si l'attaquant etait deja dans le reseau ?", options: ["Never trust", "Always verify", "Assume breach", "Least privilege"], answer: 2, explanation: "'Assume breach' motive la microsegmentation, le chiffrement interne et la detection d'anomalies. On suppose l'attaquant deja present pour minimiser le blast radius." }
  ]},
  { file: "quiz-08-03-csp-trusted-types-sri.html", title: "Quiz — CSP, Trusted Types & SRI", subtitle: "Module 08 — Securite (Cours 58)", questions: [
    { label: "CSP hash-only", text: "Pourquoi utiliser des hash SHA-256 plutot que 'unsafe-inline' dans une CSP ?", options: ["Les hash sont plus faciles a maintenir", "'unsafe-inline' autorise TOUS les scripts inline y compris ceux injectes par XSS, les hash n'autorisent que les scripts declares", "Les hash ameliorent les performances", "'unsafe-inline' est deprecie"], answer: 1, explanation: "Avec unsafe-inline, tout script inline s'execute. Avec des hash, le navigateur ne l'execute que si le hash correspond. Un script XSS injecte n'a pas son hash dans la CSP." },
    { label: "Trusted Types", text: "Comment deployer les Trusted Types en securite ?", options: ["Activer directement en enforcement", "D'abord en report-only pour detecter les sinks dangereux, puis enforcement une fois tout migre", "Uniquement en dev, jamais en production", "Uniquement pour les scripts tiers"], answer: 1, explanation: "En report-only, les violations sont loguees sans bloquer. On identifie tous les sinks (innerHTML, eval), on migre vers des policies, puis on passe en enforcement." },
    { label: "SRI", text: "Quel est le role de l'attribut 'integrity' dans une balise script ?", options: ["Verifier que le script vient du bon domaine", "Contenir le hash SHA du fichier attendu — le navigateur bloque si le contenu a ete modifie", "Signer le script avec une cle privee", "Executer le script hors CSP"], answer: 1, explanation: "SRI verifie que les fichiers du CDN tiers n'ont pas ete modifies. Le navigateur compare le hash du fichier telecharge au hash declare. Si different, le script est bloque." },
    { label: "X-XSS-Protection", text: "Pourquoi mettre X-XSS-Protection a 0 ?", options: ["Le header est redondant avec le firewall", "Le filtre XSS des anciens navigateurs pouvait etre EXPLOITE pour creer des XSS — la CSP le remplace", "La valeur 0 active la protection maximale", "Incompatible avec HTTPS"], answer: 1, explanation: "Le filtre XSS integre des anciens navigateurs pouvait paradoxalement etre exploite. La CSP est une protection superieure. Desactiver le filtre (0) est la recommandation." },
    { label: "CSP reporting", text: "Pourquoi rate-limiter les rapports de violation CSP ?", options: ["Economiser la bande passante", "Eviter qu'un attaquant floode le serveur de reporting via des violations CSP intentionnelles", "Respecter le RGPD", "Limiter le nombre de violations"], answer: 1, explanation: "Un attaquant peut generer des milliers de violations CSP pour DDoS le serveur de reporting. Le rate limiting (10/min/IP) protege tout en conservant les signaux utiles." }
  ]},
  { file: "quiz-08-04-rate-limiting-cors.html", title: "Quiz — Rate Limiting & CORS", subtitle: "Module 08 — Securite (Cours 59)", questions: [
    { label: "Sliding window", text: "Quel avantage du sliding window counter sur le fixed window ?", options: ["Moins de memoire", "Elimine le burst au bord de fenetre en interpolant entre fenetre courante et precedente", "Plus simple a implementer", "Limites plus elevees"], answer: 1, explanation: "Le fixed window permet un burst de 2x au changement de fenetre. Le sliding window counter interpole (total = count_prev * weight + count_current), garantissant le respect de la limite." },
    { label: "GDPR-safe", text: "Pourquoi hasher l'IP avec un pepper pour les cles Redis de rate limiting ?", options: ["Ameliorer les performances", "Les IPs sont des donnees personnelles RGPD et ne doivent pas etre stockees en clair", "Empecher les collisions", "Compresser les cles"], answer: 1, explanation: "SHA-256(IP + pepper) est irreversible et RGPD-compliant. Le meme IP+pepper donne toujours le meme hash pour le comptage. La rotation du pepper fait expirer les anciens compteurs." },
    { label: "CORS credentials", text: "Pourquoi ne jamais utiliser Access-Control-Allow-Origin: * avec credentials: true ?", options: ["Le wildcard est deprecie en HTTP/2", "N'importe quel site malveillant pourrait envoyer des requetes authentifiees au nom de l'utilisateur", "Le navigateur ne supporte pas cette combinaison par choix arbitraire", "Le wildcard desactive HTTPS"], answer: 1, explanation: "Avec * et credentials, tout site pourrait envoyer des requetes avec les cookies de l'utilisateur. Le navigateur refuse cette combinaison et exige une origine explicite." },
    { label: "Preflight", text: "A quoi sert la preflight request (OPTIONS) dans CORS ?", options: ["Tester la vitesse du serveur", "Verifier si la requete cross-origin complexe est autorisee AVANT de l'envoyer", "Telecharger les certificats SSL", "Synchroniser les horloges"], answer: 1, explanation: "Pour les requetes complexes (POST+JSON, headers custom), le navigateur envoie un OPTIONS pour verifier les autorisations. La vraie requete n'est envoyee que si le preflight reussit." },
    { label: "Supply chain", text: "Pourquoi utiliser 'npm ci' plutot que 'npm install' en CI ?", options: ["npm ci est plus rapide", "npm ci respecte strictement le lockfile, empechant les attaques par lockfile tampering", "npm ci installe moins de dependances", "npm ci est requis par les registres prives"], answer: 1, explanation: "npm ci echoue si le lockfile ne correspond pas au package.json, garantissant les memes versions exactes et empechant les modifications silencieuses du lockfile." }
  ]},
  { file: "quiz-08-05-sandboxing-extensions.html", title: "Quiz — Sandboxing & Extension Security", subtitle: "Module 08 — Securite (Cours 60)", questions: [
    { label: "Isolation", text: "Quel niveau d'isolation pour les plugins tiers d'un CMS ?", options: ["Import direct dans le meme DOM", "Shadow DOM", "iframe sandbox — isolation totale DOM, JS, styles, communication via postMessage", "Web Worker"], answer: 2, explanation: "L'iframe sandbox offre l'isolation totale : DOM isole, JS isole, origin separee. La communication via postMessage avec verification d'origin est le seul canal autorise." },
    { label: "allow-top-navigation", text: "Pourquoi ne JAMAIS ajouter 'allow-top-navigation' au sandbox ?", options: ["Cela ralentit la page", "Le plugin pourrait rediriger la page principale vers un site malveillant (phishing)", "Cela desactive le sandbox", "Le plugin ne fonctionnerait plus"], answer: 1, explanation: "allow-top-navigation permet au code dans l'iframe de modifier window.top.location. Un plugin malveillant pourrait rediriger vers un site de phishing." },
    { label: "timingSafeEqual", text: "Pourquoi utiliser timingSafeEqual pour verifier le manifest ?", options: ["Pour les performances", "Pour empecher les timing attacks ou l'attaquant deduit la signature octet par octet", "Pour la norme OWASP", "Pour la compatibilite navigateur"], answer: 1, explanation: "Une comparaison classique s'arrete au premier octet different. Un attaquant peut mesurer le temps et deduire la signature. timingSafeEqual prend toujours le meme temps." },
    { label: "Auto-disable", text: "Que se passe-t-il apres 10 violations de capabilities d'un plugin ?", options: ["Les violations sont juste loguees", "Le plugin est automatiquement desactive et l'admin notifie", "Le serveur redemarre", "Les capabilities sont etendues"], answer: 1, explanation: "Apres 10 violations, le plugin est auto-desactive. C'est une protection contre les plugins compromis ou malveillants — defense en profondeur." },
    { label: "CSS scope", text: "Pourquoi le CSS custom doit-il etre scope sous #site-root ?", options: ["Ameliorer les performances CSS", "Empecher le CSS custom de modifier le back-office ou d'autres zones sensibles", "Respecter les standards W3C", "Faciliter le debuggage"], answer: 1, explanation: "Sans scope, un tenant pourrait cacher des boutons de securite ou alterer l'interface d'administration. Le scope confine l'impact a la zone du site public." }
  ]},
  { file: "quiz-08-06-privacy-by-design.html", title: "Quiz — Privacy by Design & GDPR", subtitle: "Module 08 — Securite (Cours 61)", questions: [
    { label: "Privacy par defaut", text: "Quel principe exige que la vie privee soit le reglage par defaut ?", options: ["Proactif, pas reactif", "Privacy par defaut — opt-in, minimum de donnees collectees", "Securite de bout en bout", "Respect de l'utilisateur"], answer: 1, explanation: "Sans action de l'utilisateur, le minimum de donnees est collecte (opt-in, pas opt-out). L'utilisateur doit activement choisir de partager plus." },
    { label: "Droit a l'oubli", text: "Comment implementer le droit a l'oubli sans perdre les stats ?", options: ["Supprimer physiquement toutes les donnees", "Pseudonymiser les PII tout en conservant les commandes anonymisees pour la comptabilite", "Bloquer l'acces au compte", "Exporter en CSV"], answer: 1, explanation: "On pseudonymise les PII (nom -> DELETED, email -> UUID@erased.local), on anonymise les commandes (comptabilite), on supprime les sessions, et on propage aux sous-traitants." },
    { label: "CMP", text: "Pourquoi aucun script analytique ne doit se charger avant le consentement CMP ?", options: ["Pour les performances", "Le GDPR exige le consentement explicite AVANT tout traitement de donnees personnelles", "Les scripts tiers sont toujours malveillants", "Pour eviter les erreurs JS"], answer: 1, explanation: "Charger un script analytics avant le consentement constitue une collecte illegale. Le CMP doit bloquer ces scripts et ne les activer qu'apres consentement explicite." },
    { label: "PII-free analytics", text: "Comment rendre les analytics GDPR-compliant par construction ?", options: ["Google Analytics avec anonymisation", "crypto.randomUUID() par session sans tracking cross-session", "Stocker hors UE", "Consentement une seule fois"], answer: 1, explanation: "Un sessionId regenere a chaque session elimine le tracking cross-session et ne stocke aucune PII. GDPR-compliant par construction." },
    { label: "Retention", text: "Pourquoi limiter la retention des logs a 90 jours ?", options: ["Les logs occupent trop d'espace", "Les logs contiennent potentiellement des donnees personnelles et la minimisation GDPR exige de ne pas garder plus que necessaire", "C'est une limite technique", "Pour les couts cloud"], answer: 1, explanation: "Meme pseudonymises, les logs peuvent contenir des traces de donnees personnelles. Le principe de minimisation GDPR exige une retention limitee — 90 jours est la bonne pratique." }
  ]},

  // ===== 09 — Performance & Scalabilite =====
  { file: "quiz-09-01-caching-multi-niveaux.html", title: "Quiz — Caching multi-niveaux", subtitle: "Module 09 — Performance & Scalabilite (Cours 62)", questions: [
    { label: "3 niveaux", text: "Quels sont les 3 niveaux de cache et leur latence approximative ?", options: ["Browser, proxy, serveur", "CDN (~0ms edge), Redis (~1-5ms partage), DB (~10-50ms source de verite)", "L1, L2, L3 comme les caches CPU", "In-memory, disque, bande"], answer: 1, explanation: "CDN/edge (cache public, ~0ms), Redis (cache partage server-side, ~1-5ms), PostgreSQL (source de verite, ~10-50ms). Plus on est proche du client, plus c'est rapide mais limite en capacite." },
    { label: "Surrogate keys", text: "Comment fonctionne la surrogate-key invalidation ?", options: ["On purge toutes les URLs manuellement", "Chaque reponse porte des tags, on purge par tag — toutes les pages contenant ce tag sont invalidees sans connaitre les URLs", "On utilise un TTL court sur toutes les pages", "On desactive le cache apres chaque modification"], answer: 1, explanation: "Le header Surrogate-Key contient des tags (product:abc, category:shoes). Quand un produit change, on purge le tag — toutes les pages contenant ce produit sont invalidees precisement." },
    { label: "ETag", text: "Comment le mecanisme ETag economise-t-il la bande passante ?", options: ["En compressant les donnees automatiquement", "Le client envoie If-None-Match avec le ETag, le serveur repond 304 Not Modified (0 bytes) si inchange", "En stockant les donnees dans le navigateur indefiniment", "En reduisant la taille des headers HTTP"], answer: 1, explanation: "Le serveur genere un ETag (hash du contenu). Le client le renvoie dans If-None-Match. Si le contenu n'a pas change, le serveur repond 304 sans body — zero transfert de donnees." },
    { label: "Strategie par route", text: "Quelle directive Cache-Control pour un asset statique avec hash dans le nom ?", options: ["no-store", "private, max-age=3600", "public, max-age=31536000, immutable", "no-cache, must-revalidate"], answer: 2, explanation: "Un asset avec hash dans le nom (logo.abc123.svg) ne change jamais — si le contenu change, le hash change. On peut donc cacher indefiniment (1 an) avec immutable." },
    { label: "Tag-aware invalidation", text: "Pourquoi preferer l'invalidation par tag plutot que par URL ?", options: ["Les tags sont plus rapides a traiter", "Un produit peut apparaitre dans des dizaines de pages — invalider par tag purge toutes les pages concernees sans connaitre chaque URL", "Les tags sont standards HTTP", "Les URLs ne sont pas modifiables"], answer: 1, explanation: "Un produit peut etre present dans la page produit, la liste categorie, le panier, le search... Invalider par tag 'product:abc' purge toutes ces pages sans maintenir une liste d'URLs." }
  ]},
  { file: "quiz-09-02-cdn-edge-images.html", title: "Quiz — CDN, Edge Computing & Image Pipeline", subtitle: "Module 09 — Performance & Scalabilite (Cours 63)", questions: [
    { label: "Edge-first", text: "Quel TTFB viser avec une strategie CDN edge-first en Europe ?", options: ["< 5 secondes", "< 600ms (sub-600ms TTFB), ~15-50ms sur un edge hit", "< 3 secondes", "Le TTFB n'est pas mesurable"], answer: 1, explanation: "L'objectif est un TTFB < 600ms. Un edge cache hit descend a ~15-50ms. Le cache est invalide selectivement via surrogate keys quand le contenu change." },
    { label: "format=auto", text: "Pourquoi utiliser format=auto dans le pipeline d'images ?", options: ["Pour reduire la complexite du code", "Le serveur detecte le header Accept du navigateur et sert le format optimal (AVIF > WebP > JPEG)", "Pour standardiser tous les formats en PNG", "Pour empecher le vol d'images"], answer: 1, explanation: "format=auto detecte le header Accept et sert AVIF (meilleure compression), WebP ou JPEG fallback. Le client recoit toujours le meilleur rapport qualite/taille sans gestion manuelle." },
    { label: "SHA-256 dedup", text: "Comment la deduplication SHA-256 economise-t-elle du stockage ?", options: ["En compressant les images automatiquement", "En calculant le hash de chaque fichier et en ne stockant qu'une seule copie physique pour les fichiers identiques", "En supprimant les anciennes versions", "En reduisant la resolution des images"], answer: 1, explanation: "Si 2 tenants uploadent la meme image, le hash SHA-256 est identique. On stocke un seul fichier physique avec N references. Economie typique : 30-40% de stockage." },
    { label: "srcset responsive", text: "A quoi sert l'attribut srcset dans une balise picture ?", options: ["A afficher des images differentes selon le theme", "A proposer plusieurs tailles d'image pour que le navigateur charge celle adaptee a la taille d'ecran et a la resolution", "A precharger toutes les images en parallele", "A animer les images au scroll"], answer: 1, explanation: "srcset avec sizes permet au navigateur de choisir la meilleure image selon la largeur d'ecran et la resolution (retina). Un mobile 400px ne charge pas l'image 1200px." },
    { label: "stale-while-revalidate", text: "Que fait la directive stale-while-revalidate ?", options: ["Elle bloque la requete jusqu'a la revalidation", "Elle sert le contenu stale immediatement tout en revalidant en arriere-plan pour le prochain visiteur", "Elle supprime le cache apres expiration", "Elle desactive le cache pour les requetes lentes"], answer: 1, explanation: "stale-while-revalidate offre une UX fluide : le visiteur recoit le cache (meme expire) immediatement, pendant que le CDN revalide en background. Le prochain visiteur aura le contenu frais." }
  ]},
  { file: "quiz-09-03-load-balancing.html", title: "Quiz — Load Balancing", subtitle: "Module 09 — Performance & Scalabilite (Cours 64)", questions: [
    { label: "Algorithmes", text: "Quel algorithme de load balancing choisir quand les requetes ont des durees tres variables ?", options: ["Round-robin", "Least connections — le serveur avec le moins de connexions actives recoit la suivante", "IP hash", "Random"], answer: 1, explanation: "Avec des durees variables, round-robin peut surcharger un serveur qui traite des requetes longues. Least connections distribue intelligemment vers le serveur le moins occupe." },
    { label: "Layer 4 vs 7", text: "Quelle est la difference cle entre Layer 4 et Layer 7 load balancing ?", options: ["Layer 4 est pour le web, Layer 7 pour les bases de donnees", "Layer 4 forward les paquets TCP sans inspection, Layer 7 parse le HTTP et peut router par URL/header", "Layer 4 est plus intelligent que Layer 7", "Il n'y a pas de difference significative"], answer: 1, explanation: "Layer 4 (TCP) est rapide mais aveugle au contenu. Layer 7 (HTTP) peut router /api vers un pool, /static vers un autre, inspecter les cookies — plus lent mais intelligent." },
    { label: "Health checks", text: "Quelle est la difference entre liveness et readiness probe en Kubernetes ?", options: ["Ce sont des synonymes", "Liveness verifie si le process est vivant (sinon restart), readiness s'il peut servir du trafic (sinon retire du LB)", "Liveness est pour la DB, readiness pour l'API", "Liveness est plus rapide que readiness"], answer: 1, explanation: "Liveness echoue -> K8s restart le pod. Readiness echoue -> K8s retire le pod du load balancer mais ne le restart pas. Un pod peut etre vivant mais pas pret (DB pas connectee)." },
    { label: "Stateless", text: "Pourquoi les architectures modernes preferent-elles le stateless aux sticky sessions ?", options: ["Le stateless est plus facile a coder", "En stateless, l'etat est dans Redis/DB, le scaling horizontal est trivial et la perte d'un serveur ne perd pas les sessions", "Les sticky sessions sont plus rapides", "Le stateless consomme moins de memoire"], answer: 1, explanation: "Avec sticky sessions, un serveur down = sessions perdues. En stateless, tout l'etat est dans Redis/DB, chaque serveur est interchangeable, le scaling horizontal est trivial." },
    { label: "Graceful shutdown", text: "Quel est le bon ordre pour un graceful shutdown ?", options: ["Fermer la DB, arreter le serveur, tuer le process", "SIGTERM -> stop accept -> readiness false -> drain connections -> close resources -> exit", "Tuer le process immediatement avec SIGKILL", "Notifier les clients puis arreter"], answer: 1, explanation: "Le graceful shutdown arrete d'accepter de nouvelles connexions, passe readiness a false (LB retire le noeud), attend que les requetes en cours finissent, ferme DB/Redis, puis exit." }
  ]},
  { file: "quiz-09-04-scaling-cloud-native.html", title: "Quiz — Scaling & Cloud-Native", subtitle: "Module 09 — Performance & Scalabilite (Cours 65)", questions: [
    { label: "Horizontal vs Vertical", text: "Quel est l'avantage principal du scaling horizontal sur le vertical ?", options: ["Il est moins cher", "Pas de plafond physique, resilience (1 pod down est OK), et cout lineaire — mais stateless obligatoire", "Il est plus simple a implementer", "Il ne necessite pas de load balancer"], answer: 1, explanation: "Le scaling vertical a un plafond physique et est un SPOF. Le scaling horizontal n'a pas de limite, offre la resilience, mais exige que les containers soient stateless." },
    { label: "Little's Law", text: "Avec 200 req/s et 50ms de latence moyenne, combien de requetes sont in-flight ?", options: ["200", "10 (L = 200 * 0.05)", "50", "4000"], answer: 1, explanation: "Little's Law : L = lambda * W = 200 * 0.05 = 10 requetes in-flight. Si chaque pod gere 5 connexions, il faut minimum 2 pods + marge de securite." },
    { label: "Init container", text: "A quoi sert un init container en Kubernetes ?", options: ["A initialiser le cluster K8s", "A executer des taches AVANT le container principal (migrations DB, wait-for-db, warm cache)", "A surveiller les autres containers", "A gerer les logs du pod"], answer: 1, explanation: "L'init container s'execute et se termine avant que le container principal ne demarre. Si la migration echoue, le pod ne demarre pas — les migrations sont separees du runtime." },
    { label: "Sidecar pattern", text: "Quel est le role du pattern sidecar en cloud-native ?", options: ["Remplacer le container principal en cas de panne", "Un container auxiliaire a cote de l'app qui gere des concerns transverses (mTLS proxy, log collector)", "Doubler les ressources du pod", "Fournir un backup des donnees"], answer: 1, explanation: "Le sidecar (ex: Envoy proxy pour mTLS, agent de logging) tourne dans le meme pod que l'app. Il gere des concerns transverses sans modifier le code applicatif." },
    { label: "HPA", text: "Sur quelles metriques le HorizontalPodAutoscaler scale-t-il typiquement ?", options: ["Le nombre de requetes HTTP", "L'utilisation CPU et memoire des pods (ex: scale up a 70% CPU)", "La taille du disque", "Le nombre de users connectes"], answer: 1, explanation: "Le HPA surveille l'utilisation CPU/memoire. Quand elle depasse le seuil (ex: 70% CPU), il ajoute des replicas. Des metriques custom (requetes, latence) sont aussi possibles." }
  ]},
  { file: "quiz-09-05-sharding-replication.html", title: "Quiz — Sharding & Replication", subtitle: "Module 09 — Performance & Scalabilite (Cours 66)", questions: [
    { label: "Replication vs Sharding", text: "Quelle est la difference entre replication et sharding ?", options: ["Ce sont des synonymes pour la haute disponibilite", "La replication duplique les memes donnees (plus de lectures), le sharding divise les donnees (plus de capacite totale)", "Le sharding est pour le cache, la replication pour la DB", "La replication est horizontale, le sharding vertical"], answer: 1, explanation: "Replication = memes donnees sur plusieurs noeuds (primary pour ecritures, replicas pour lectures). Sharding = chaque shard contient un sous-ensemble different des donnees." },
    { label: "Shard key", text: "Pourquoi tenant_id est-il souvent le meilleur shard key ?", options: ["Il est toujours numerique", "Haute cardinalite, distribution uniforme, present dans toutes les requetes — chaque query va directement au bon shard", "Il est court en memoire", "Il est indexe automatiquement"], answer: 1, explanation: "tenant_id a une haute cardinalite, une distribution relativement uniforme, et est present dans pratiquement toutes les requetes multi-tenant. Cela evite le scatter-gather." },
    { label: "Scatter-gather", text: "Pourquoi le scatter-gather est-il a eviter dans un systeme sharde ?", options: ["Il consomme trop de memoire", "Sans shard key dans la requete, elle est envoyee a TOUS les shards puis fusionnee — tres lent", "Il cause des deadlocks", "Il n'est pas supporte par PostgreSQL"], answer: 1, explanation: "SELECT * FROM orders WHERE total > 1000 sans shard key va a tous les shards. Avec tenant_id dans la WHERE clause, la requete va directement au bon shard." },
    { label: "Quand sharder", text: "Quand le sharding est-il premature ?", options: ["Toujours, il ne faut jamais sharder", "Quand PostgreSQL single node suffit (< 1TB, < 10K req/s) et que des read replicas resolvent le probleme", "Quand on a plus de 10 tables", "Quand on utilise un ORM"], answer: 1, explanation: "PostgreSQL single node tient jusqu'a ~1TB et ~10K req/s. Avant de sharder, utiliser des read replicas et le partitioning natif. Le sharding ajoute une complexite significative." },
    { label: "Replication sync", text: "Quel est le tradeoff entre replication synchrone et asynchrone ?", options: ["La synchrone est toujours meilleure", "La synchrone garantit la consistance (finance) mais ajoute de la latence, l'asynchrone est plus rapide mais eventual consistency", "L'asynchrone est toujours meilleure", "Il n'y a pas de difference"], answer: 1, explanation: "Synchrone : le primary attend la confirmation du replica = consistance forte mais latence plus elevee. Asynchrone : le primary n'attend pas = performant mais replication lag possible." }
  ]},
  { file: "quiz-09-06-serverless.html", title: "Quiz — Serverless Architecture", subtitle: "Module 09 — Performance & Scalabilite (Cours 67)", questions: [
    { label: "Cold start", text: "Qu'est-ce qu'un cold start en serverless et comment le mitiguer ?", options: ["Un bug au demarrage du serveur", "Le temps de demarrage d'une nouvelle instance (500ms-5s) — mitigable avec provisioned concurrency ou runtimes legers", "Un echec de connexion a la base de donnees", "Un timeout sur la premiere requete"], answer: 1, explanation: "Le cold start inclut le telechargement du code, l'init du runtime et le chargement du handler. Node.js (~650ms) est plus rapide que Java (~2-5s). Le provisioned concurrency pre-chauffe les instances." },
    { label: "Break-even", text: "A partir de combien d'invocations les containers deviennent plus rentables que le serverless ?", options: ["100 000/mois", "Environ 3-5 millions d'invocations par mois", "10 millions/mois", "Le serverless est toujours moins cher"], answer: 1, explanation: "En dessous de ~3-5M invocations/mois, le serverless est quasi gratuit. Au-dela, le cout par invocation depasse celui d'un container 24/7. Le break-even exact depend du runtime et de la memoire." },
    { label: "Quand serverless", text: "Dans quel cas le serverless est-il le meilleur choix ?", options: ["API principale a forte latence constante requise", "Trafic sporadique, taches event-driven asynchrones, et faible volume", "Applications stateful avec sessions longues", "Services qui tournent en continu pendant des heures"], answer: 1, explanation: "Le serverless excelle pour le trafic imprevisible/sporadique et les taches event-driven (resize image, envoyer email). Pour une API principale a latence constante, les containers sont preferes." },
    { label: "Edge Functions", text: "Quel est l'avantage des Edge Functions par rapport aux Lambda classiques ?", options: ["Elles coutent moins cher", "Cold start < 5ms (V8 isolates), execution sur le CDN edge node le plus proche de l'utilisateur", "Elles supportent tous les langages", "Elles ont acces complet a Node.js"], answer: 1, explanation: "Les Edge Functions (Cloudflare Workers, Vercel Edge) utilisent des V8 isolates (pas de container) pour un cold start < 5ms. Elles s'executent sur l'edge node le plus proche, ideales pour auth, redirects, A/B testing." },
    { label: "Architecture hybride", text: "Qu'est-ce qu'une architecture hybride containers + serverless ?", options: ["Utiliser deux cloud providers en meme temps", "API principales en containers (latence constante) + taches asynchrones en serverless (cout optimise)", "Containers en dev, serverless en production", "Serverless pour le frontend, containers pour le backend"], answer: 1, explanation: "L'API principale reste en container pour la latence constante. Les taches event-driven (thumbnails, emails, cleanup) vont en serverless pour le pay-per-invocation. Le meilleur des deux mondes." }
  ]},

  // ===== 10 — Observabilite & DevOps =====
  { file: "quiz-10-01-logging-structure.html", title: "Quiz — Logging structure", subtitle: "Module 10 — Observabilite & DevOps (Cours 68)", questions: [
    { label: "JSON vs texte libre", text: "Pourquoi le logging structure JSON est-il superieur au texte libre ?", options: ["Il est plus lisible pour les humains", "Il est parsable par machine, filtrable, aggregable et alertable — les outils comme Loki peuvent exploiter les champs structures", "Il prend moins de place en stockage", "Il est requis par la norme HTTP"], answer: 1, explanation: "Le JSON est parsable par machine. On peut filtrer (tenantId=acme), agreger (count order.created par heure), et alerter (error rate > 1%). Le texte libre necessite des regex fragiles." },
    { label: "PII-free", text: "Que faire des emails et IPs dans les logs de production ?", options: ["Les stocker en clair pour le debug", "Les hasher (SHA-256) ou utiliser des UUIDs de session — jamais de PII en clair", "Les chiffrer avec AES-256", "Les supprimer completement des logs"], answer: 1, explanation: "Les emails et IPs sont des PII (GDPR). On les pseudonymise avec SHA-256 ou on utilise des identifiants non-PII (random UUID de session, role utilisateur)." },
    { label: "Correlation ID", text: "A quoi sert un traceId propage entre services ?", options: ["A mesurer la bande passante", "A reconstituer le parcours complet d'une requete utilisateur a travers tous les services distribues", "A identifier l'utilisateur qui a fait la requete", "A synchroniser les horloges des serveurs"], answer: 1, explanation: "Le traceId, genere au point d'entree et propage via X-Trace-Id, permet de retrouver tous les logs correspondant a une meme action utilisateur dans un systeme distribue." },
    { label: "Log levels", text: "A quel log level correspond 'le pager sonne a 3h du matin' ?", options: ["DEBUG", "INFO", "WARN", "ERROR"], answer: 3, explanation: "ERROR = pager a 3h (action requise immediatement), WARN = a regarder demain, INFO = evenement attendu, DEBUG = detail technique pour dev/staging uniquement." },
    { label: "Event naming", text: "Quelle convention de nommage pour les messages de log ?", options: ["Des phrases libres en langue naturelle", "entity.action — ex: order.created, user.logged_in, content.published", "Des codes numeriques comme les codes HTTP", "Le nom de la fonction qui logue"], answer: 1, explanation: "La convention entity.action est parsable, filtrable et consistante. On peut facilement compter les order.created, alerter sur les webhook.failed, etc." }
  ]},
  { file: "quiz-10-02-monitoring-alerting-slos.html", title: "Quiz — Monitoring, Alerting & SLOs", subtitle: "Module 10 — Observabilite & DevOps (Cours 69)", questions: [
    { label: "3 signaux OTel", text: "Quels sont les 3 signaux OpenTelemetry et leur role ?", options: ["CPU, RAM, disque", "Metrics (tendances numeriques), Traces (parcours requete), Logs (detail evenements) — correles via traceId", "Request, response, error", "Input, process, output"], answer: 1, explanation: "Metrics (Prometheus) pour les tendances, Traces (Tempo/Jaeger) pour le parcours d'une requete, Logs (Loki) pour le detail. Les 3 sont correles via le traceId." },
    { label: "Error budget", text: "Que signifie un SLO de 99.9% sur 30 jours en termes de budget d'erreur ?", options: ["0.1% d'erreurs autorisees soit 43 minutes de downtime tolere", "99.9% de uptime garanti contractuellement", "1 erreur par jour maximum", "43 heures de maintenance planifiee"], answer: 0, explanation: "99.9% = 0.1% de budget d'erreur = 30j * 24h * 60min * 0.001 = 43.2 minutes de downtime tolere. Budget epuise = stop features, focus fiabilite." },
    { label: "Multi-window", text: "Pourquoi utiliser des alertes multi-window burn-rate plutot que single-window ?", options: ["Pour economiser les ressources de monitoring", "Un single-window genere trop de faux positifs sur des spikes temporaires — le multi-window confirme la tendance", "Les outils ne supportent que le multi-window", "Pour respecter les SLAs contractuels"], answer: 1, explanation: "Un spike temporaire declenche une alerte single-window. Le multi-window (1h + 6h + 3j) confirme que la degradation est reelle et durable avant de pager l'equipe." },
    { label: "Histogram", text: "Pourquoi utiliser un Histogram plutot qu'un Counter pour la latence HTTP ?", options: ["Le Counter est plus precis", "L'Histogram capture la distribution des valeurs et permet de calculer les percentiles (p95, p99)", "Le Counter est deprecie pour la latence", "L'Histogram consomme moins de memoire"], answer: 1, explanation: "Un Counter ne donne que le total. Un Histogram capture la distribution et permet histogram_quantile(0.95, ...) pour obtenir le p95. C'est essentiel pour les SLOs." },
    { label: "RUM", text: "Pourquoi collecter les Core Web Vitals avec du RUM plutot que du synthetic monitoring ?", options: ["Le RUM est moins cher", "Le RUM mesure l'experience des VRAIS utilisateurs (devices variees, reseaux reels), pas un test synthetique dans des conditions ideales", "Le synthetic monitoring est deprecie", "Le RUM est plus facile a configurer"], answer: 1, explanation: "Le RUM (Real User Monitoring) collecte LCP, CLS, INP sur les vrais devices et reseaux des utilisateurs. Le synthetic monitoring teste dans des conditions ideales qui ne refletent pas la realite." }
  ]},
  { file: "quiz-10-03-distributed-tracing.html", title: "Quiz — Distributed Tracing", subtitle: "Module 10 — Observabilite & DevOps (Cours 70)", questions: [
    { label: "Trace vs Span", text: "Quelle est la relation entre une trace et un span ?", options: ["Ce sont des synonymes", "Une trace est le parcours complet, un span est une etape — les spans forment une hierarchie parent/enfant dans la trace", "Un span contient plusieurs traces", "La trace mesure le temps, le span mesure la memoire"], answer: 1, explanation: "La trace = parcours complet d'une requete (identifiee par traceId). Chaque span = une etape (DB query, appel HTTP, traitement). Les spans ont un parentSpanId formant un arbre." },
    { label: "W3C Trace Context", text: "Comment le contexte de trace se propage-t-il entre services ?", options: ["Via une base de donnees partagee", "Via le header HTTP 'traceparent' contenant version, traceId, spanId et flags", "Via un message broker dedie", "Via les cookies du navigateur"], answer: 1, explanation: "Le header W3C traceparent (00-traceId-spanId-flags) est propage automatiquement. Chaque service cree un nouveau spanId mais garde le meme traceId, correlant toute la chaine." },
    { label: "Sampling", text: "Quelle strategie de sampling en production haute charge ?", options: ["100% de toutes les traces", "1% des traces normales (head-based) + 100% des erreurs et traces lentes (tail-based)", "0% en production, 100% en staging", "Sampling aleatoire sans distinction"], answer: 1, explanation: "1% en head-based pour les traces normales. Le tail-based conserve 100% des erreurs et traces > 1s — les plus utiles pour le debug. 100% en staging." },
    { label: "Tracing vs Logging", text: "Quel probleme le tracing resout-il que le logging seul ne peut pas ?", options: ["Le tracing est plus rapide que le logging", "Le tracing montre la latence ENTRE les etapes (queues, connection pool), pas seulement DANS les etapes", "Le tracing remplace completement le logging", "Le tracing est gratuit contrairement au logging"], answer: 1, explanation: "Les logs montrent que chaque service est rapide individuellement. Le tracing revele les temps d'attente entre les services (connection pool epuise, queue pleine) invisibles dans les logs." },
    { label: "Baggage", text: "A quoi sert le baggage en OpenTelemetry ?", options: ["A stocker les logs de chaque service", "A propager du contexte metier (tenantId, feature flags) automatiquement a travers toute la chaine de services", "A compresser les donnees de trace", "A authentifier les services entre eux"], answer: 1, explanation: "Le baggage propage des key-values metier automatiquement. Service A pose tenantId=acme, Service B le recoit sans configuration. Utile pour les metriques per-tenant et le feature flag propagation." }
  ]},
  { file: "quiz-10-04-cicd-feature-flags-deploy.html", title: "Quiz — CI/CD, Feature Flags & Deploy", subtitle: "Module 10 — Observabilite & DevOps (Cours 71)", questions: [
    { label: "Blue/Green vs Canary", text: "Quelle est la difference entre Blue/Green et Canary deployment ?", options: ["Ce sont des synonymes", "Blue/Green bascule 100% du trafic instantanement (rollback = rebascule), Canary envoie d'abord 5% puis augmente progressivement", "Blue/Green est pour le frontend, Canary pour le backend", "Canary coute plus cher que Blue/Green"], answer: 1, explanation: "Blue/Green = deux environnements complets, bascule tout-ou-rien. Canary = 5% du trafic vers la nouvelle version, observer, augmenter. Canary a un blast radius minimal." },
    { label: "Feature flags", text: "Quel type de feature flag permet de modifier le comportement sans redeployer ?", options: ["Build-time (env vars)", "Runtime (config DB/Redis) — modifiable sans redeploy, rollout progressif possible", "Compile-time (preprocesseur)", "Les feature flags necessitent toujours un redeploy"], answer: 1, explanation: "Les runtime flags sont stockes en DB/Redis et modifiables sans redeploy. On peut activer/desactiver une feature, ajuster le rollout (25% -> 50% -> 100%), ou kill switch instantanement." },
    { label: "Zero-downtime", text: "Pourquoi les migrations DB doivent-elles etre backward-compatible pour le zero-downtime ?", options: ["Pour que les migrations soient plus rapides", "Pendant le rolling update, v1 et v2 cohabitent — les deux versions doivent pouvoir lire/ecrire dans le meme schema", "Pour eviter les locks sur les tables", "Pour respecter les conventions de nommage"], answer: 1, explanation: "Pendant un rolling update, des pods v1 et v2 tournent simultanement. Si v2 renomme une colonne, v1 ne peut plus lire. L'expand-contract pattern ajoute d'abord la nouvelle colonne, puis supprime l'ancienne plus tard." },
    { label: "Quality gates", text: "Quel est l'ordre correct des quality gates en CI ?", options: ["Deploy, puis tester", "Lint -> Typecheck -> Unit tests -> Security scan -> Build -> Integration tests -> Load test", "Build, puis tout le reste en parallele", "Les tests sont optionnels en CI"], answer: 1, explanation: "Chaque gate est un checkpoint. Les gates rapides (lint, typecheck) bloquent tot, les gates lentes (integration, load test) s'executent seulement si les precedentes passent." },
    { label: "Rollout progressif", text: "Comment un feature flag hash-based garantit-il un rollout coherent ?", options: ["Il utilise un generateur aleatoire a chaque requete", "Il hash l'userId + flagName, garantissant que le meme utilisateur voit toujours la meme version", "Il bascule tous les utilisateurs en meme temps", "Il utilise l'adresse IP de l'utilisateur"], answer: 1, explanation: "hash(userId + flagName) % 100 donne un nombre stable. Si rollout=25%, les users dont le hash < 25 voient la feature. Le meme user voit toujours la meme version — pas de flickering." }
  ]},
  { file: "quiz-10-05-infrastructure-as-code.html", title: "Quiz — Infrastructure as Code", subtitle: "Module 10 — Observabilite & DevOps (Cours 72)", questions: [
    { label: "IaC vs Click-ops", text: "Quel est l'avantage fondamental de l'IaC sur le click-ops ?", options: ["L'IaC est plus rapide a executer", "L'infra est du code versionne : reproductible, reviewable (PR), rollback (git revert), et le code EST la documentation", "L'IaC est gratuit", "L'IaC ne necessite pas de cloud provider"], answer: 1, explanation: "L'IaC traite l'infra comme du code dans git. Reproductible (meme commande = meme infra), reviewable (PR), rollback (git revert), documentee (le code est la doc)." },
    { label: "State remote", text: "Pourquoi le state Terraform doit-il etre remote (S3 + DynamoDB) en equipe ?", options: ["Le state local est trop volumineux", "Le state remote empeche les conflits (DynamoDB lock), est chiffre (secrets), et partage entre les membres de l'equipe", "Le state remote est plus rapide", "Terraform ne supporte pas le state local"], answer: 1, explanation: "Le state contient des secrets et doit etre chiffre. Le DynamoDB lock empeche 2 personnes d'appliquer en meme temps. En equipe, le state local cause des conflits et des pertes." },
    { label: "GitOps", text: "Quel est le principe fondamental du GitOps avec ArgoCD ?", options: ["Deployer manuellement depuis la console K8s", "Le repo git est la source de verite — le cluster converge TOUJOURS vers l'etat declare dans git", "Utiliser git uniquement pour le code applicatif", "ArgoCD remplace Terraform"], answer: 1, explanation: "ArgoCD watch le repo git, detecte les changements, et synchronise le cluster. Si quelqu'un modifie manuellement le cluster, ArgoCD le remet en conformite (self-healing)." },
    { label: "Drift detection", text: "Qu'est-ce que le drift en IaC et comment le detecter ?", options: ["Un bug dans le code Terraform", "Une difference entre l'etat declare (code) et l'etat reel (cloud) — detecte par 'terraform plan'", "Un changement de version du provider", "Une erreur de syntaxe HCL"], answer: 1, explanation: "Le drift survient quand quelqu'un modifie l'infra via la console sans mettre a jour le code. 'terraform plan' compare l'etat desire vs reel et signale les ecarts." },
    { label: "Immutable infra", text: "Pourquoi l'infrastructure immutable est-elle preferee a la mutable ?", options: ["Elle consomme moins de ressources", "Jamais de modification in-place — nouveau container/VM a chaque deploy, pas de drift, etat reproductible", "Elle est moins chere", "Elle ne necessite pas de CI/CD"], answer: 1, explanation: "En mutable, SSH + apt upgrade cree du drift. En immutable, chaque deploy cree un nouveau container/VM identique. L'ancien est detruit. Pas de configuration drift possible." }
  ]},

  // ===== 11 — Testing Architecture =====
  { file: "quiz-11-01-pyramide-tests-a11y.html", title: "Quiz — Pyramide de tests & Accessibilite", subtitle: "Module 11 — Testing (Cours 73)", questions: [
    { label: "Pyramide", text: "Quelle est la repartition ideale de la pyramide de tests ?", options: ["50% E2E, 30% integration, 20% unit", "~60% unit (rapides, stables), ~30% integration (API, DB), ~10% E2E (parcours critiques)", "100% unit tests suffit", "La repartition n'a pas d'importance"], answer: 1, explanation: "60% unit (rapides, < 1ms, stables), 30% integration (API routes, DB, 100ms-1s), 10% E2E (parcours utilisateur critiques, 5-30s). Le rapport cout/benefice est optimal." },
    { label: "Honeycomb", text: "Quand inverser la pyramide en 'honeycomb' ?", options: ["Toujours, la pyramide est obsolete", "Pour les microservices minces avec peu de logique pure et beaucoup d'I/O — plus d'integration, moins de unit", "Uniquement pour les tests de performance", "Quand on manque de developpeurs"], answer: 1, explanation: "Un service mince qui fait surtout de l'I/O a peu de logique pure a tester en unit. Un unit test qui mock tout ne teste rien d'utile. L'integration teste les vrais comportements." },
    { label: "A11y axe-core", text: "Que detecte axe-core dans les tests d'accessibilite ?", options: ["Les problemes de performance", "Les violations WCAG automatisables : images sans alt, contraste insuffisant, ARIA invalide, labels manquants", "Les erreurs JavaScript", "Les failles de securite XSS"], answer: 1, explanation: "axe-core detecte automatiquement les violations WCAG : images sans alt, contraste < 4.5:1, ARIA invalide, touch targets < 44px. Combine avec Playwright pour la navigation clavier." },
    { label: "Focus trap", text: "Pourquoi une modale doit-elle avoir un focus trap ?", options: ["Pour ameliorer les performances", "Pour que le Tab clavier ne sorte pas de la modale — les utilisateurs de lecteur d'ecran restent dans le contexte", "Pour empecher le scroll de la page", "Pour le style visuel"], answer: 1, explanation: "Sans focus trap, Tab sort de la modale et navigue dans la page derriere — confus pour les utilisateurs de clavier/lecteur d'ecran. Le focus doit boucler a l'interieur de la modale." },
    { label: "Coverage", text: "Pourquoi viser 100% de code coverage est-il un mauvais objectif ?", options: ["C'est techniquement impossible", "Ca pousse a tester les getters/setters au lieu de la logique critique — faux sentiment de securite", "Les outils de coverage sont imprecis", "100% est trop facile a atteindre"], answer: 1, explanation: "100% pousse a tester du code trivial (getters) au lieu de la logique complexe. L'objectif est la coverage des branches critiques : logique metier 90%+, utilitaires 80%+, generated code exclus." }
  ]},
  { file: "quiz-11-02-test-doubles-patterns.html", title: "Quiz — Test doubles & patterns", subtitle: "Module 11 — Testing (Cours 74)", questions: [
    { label: "5 types", text: "Quelle est la difference entre un stub et un fake ?", options: ["Ce sont des synonymes", "Un stub retourne une valeur predeterminee sans logique, un fake a une implementation simplifiee mais fonctionnelle (ex: InMemoryRepository)", "Un stub est pour le frontend, un fake pour le backend", "Un fake est plus rapide qu'un stub"], answer: 1, explanation: "Stub : getUser() retourne toujours {id:'1', name:'Alice'} — pas de logique. Fake : InMemoryRepository avec un vrai Map, des methodes find/save — implementation simplifiee mais fonctionnelle." },
    { label: "MSW", text: "Pourquoi utiliser MSW plutot que mocker axios/fetch directement ?", options: ["MSW est plus rapide", "MSW intercepte les vraies requetes HTTP — il teste le chemin complet (serialisation, headers, status codes)", "MSW est requis par les frameworks modernes", "MSW fonctionne sans Node.js"], answer: 1, explanation: "Mocker axios ne teste que l'appel de fonction. MSW intercepte au niveau reseau et teste le vrai chemin HTTP : fetch, headers, body parsing, status codes." },
    { label: "Quand NE PAS mocker", text: "Quand ne faut-il PAS mocker en tests d'integration ?", options: ["Les appels reseau externes", "La base de donnees — utiliser des test containers pour tester les vrais comportements SQL", "Les dependances lentes", "Le non-determinisme (Date.now)"], answer: 1, explanation: "En integration, mocker la DB ne teste rien d'utile. Les test containers demarrent un vrai PostgreSQL, executent les migrations et testent les contraintes, triggers et indexes reels." },
    { label: "Auth mock pattern", text: "Comment le pattern auth mock simplifie-t-il les tests ?", options: ["Il desactive l'authentification completement", "AUTH_MODE=mock en dev/tests utilise un MockAuthGuard avec un user hardcode, AUTH_MODE=oidc en production", "Il genere automatiquement des tokens JWT valides", "Il bypass toutes les autorisations"], answer: 1, explanation: "Le MockAuthGuard injecte un utilisateur de test sans appeler Keycloak. Meme interface que le vrai guard — le code applicatif ne voit pas la difference. Switch via variable d'environnement." },
    { label: "Fake repository", text: "Quel est l'avantage d'un InMemoryRepository pour les tests unitaires ?", options: ["Il est plus lent qu'un vrai repository", "Il est rapide (pas de DB), seedable (pre-remplir), et permet de tester la logique metier isolement", "Il remplace les tests d'integration", "Il est requis par les frameworks de test"], answer: 1, explanation: "L'InMemoryRepository avec un simple Map est instantane, seedable (inject des donnees de test), et isole la logique metier de l'infrastructure. Ideal pour les tests unitaires." }
  ]},
  { file: "quiz-11-03-contract-testing.html", title: "Quiz — Contract Testing", subtitle: "Module 11 — Testing (Cours 75)", questions: [
    { label: "Probleme resolu", text: "Quel probleme les contract tests resolvent-ils ?", options: ["Les problemes de performance entre services", "Un dev backend renomme un champ et casse le frontend en production — le contract test detecte le breaking change AVANT le merge", "Les conflits de merge dans le code", "Les problemes de deploiement"], answer: 1, explanation: "Le consumer definit ses attentes (schema), le provider verifie qu'il les respecte. Un rename name -> title casse le contract test avant le merge, pas en production." },
    { label: "Pact flow", text: "Quel est le flux du consumer-driven contract testing avec Pact ?", options: ["Le provider definit le contrat, le consumer le respecte", "Le consumer ecrit ses attentes -> genere un pact file -> le provider verifie sa reponse reelle contre ce pact file", "Les deux equipes se mettent d'accord sur un schema commun", "Un outil genere automatiquement les tests"], answer: 1, explanation: "C'est consumer-driven : le front definit ce dont il a besoin, genere un pact file (JSON), puis le back verifie que sa vraie API respecte ce contrat avec des state handlers." },
    { label: "Contract vs Integration", text: "Quelle est la difference entre un contract test et un test d'integration ?", options: ["Ce sont des synonymes", "Le contract teste la FORME (schema de la reponse), l'integration teste le COMPORTEMENT (logique metier complete)", "L'integration est plus rapide", "Le contract necessite un serveur reel"], answer: 1, explanation: "Contract = est-ce que la reponse contient {name: string} ? Integration = est-ce que la creation de commande reserve le stock et envoie un email ? Le scope est different." },
    { label: "Quand utiliser", text: "Quand les contract tests sont-ils les plus utiles ?", options: ["Pour un monolithe full-stack avec une seule equipe", "Quand il y a plusieurs consumers (web, mobile, tiers) ou des equipes separees front/back", "Pour les prototypes et MVP", "Uniquement pour les API GraphQL"], answer: 1, explanation: "Plusieurs consumers, equipes separees, ou API publique = le contract test previent les casses. Pour un monolithe full-stack avec une equipe, les tests d'integration suffisent." },
    { label: "OpenAPI alternative", text: "Quelle est l'alternative legere aux contract tests Pact ?", options: ["Pas d'alternative, Pact est obligatoire", "La validation de schema OpenAPI + detection de breaking changes avec openapi-diff", "Les tests E2E remplacent les contract tests", "Les tests unitaires du controller"], answer: 1, explanation: "Si Pact est trop lourd, valider la spec OpenAPI automatiquement et utiliser openapi-diff pour detecter les breaking changes en CI. Moins puissant mais plus leger." }
  ]},
  { file: "quiz-11-04-load-testing-production.html", title: "Quiz — Load Testing & Testing in Production", subtitle: "Module 11 — Testing (Cours 76)", questions: [
    { label: "Profiles k6", text: "Quel profile k6 utiliser pour detecter les memory leaks ?", options: ["Smoke (1-5 VUs, 2min)", "Soak — 100 VUs pendant 2-8h pour detecter les fuites memoire et connection leaks", "Stress (300+ VUs)", "Spike (0 -> 500 VUs)"], answer: 1, explanation: "Le soak test maintient une charge constante sur une longue duree. Si la memoire croit continuellement sans redescendre, c'est un leak. Impossible a detecter avec un test court." },
    { label: "Metriques", text: "Quels seuils de metriques surveiller pendant un load test ?", options: ["Uniquement le nombre de requetes par seconde", "p95 < 300ms, error rate < 1%, throughput stable, CPU < 70%, memoire stable (pas de croissance continue)", "Uniquement le temps de reponse moyen", "Le nombre de connexions ouvertes uniquement"], answer: 1, explanation: "Le p95 (pas la moyenne) revele les latences reelles. L'error rate doit rester bas. Le CPU > 90% indique la saturation. Une memoire qui croit continuellement signale un leak." },
    { label: "Synthetic monitoring", text: "Quel est l'avantage du synthetic monitoring sur le RUM ?", options: ["Il est plus precis", "Il detecte les pannes AVANT les utilisateurs en executant des scenarios toutes les 5 minutes", "Il ne necessite pas de code", "Il est gratuit"], answer: 1, explanation: "Le synthetic monitoring execute des scenarios reels (login -> search -> produit) toutes les 5 minutes. Si ca echoue, l'equipe est alertee AVANT que les utilisateurs ne soient impactes." },
    { label: "Testing in production", text: "Comment tester en production de maniere securisee ?", options: ["Deployer directement a 100% et observer", "Canary 5% + observer metriques (error rate, latence, business KPIs) + rollback automatique si regression", "Tester uniquement en staging, jamais en production", "Demander aux utilisateurs de tester manuellement"], answer: 1, explanation: "Canary 5% du trafic, comparer les metriques avec le baseline. Si OK -> promote a 100%. Si regression -> rollback automatique a 0%. Les feature flags permettent un kill switch instantane." },
    { label: "CI integration", text: "Quel profile k6 executer sur chaque merge request en CI ?", options: ["Load test complet (30 min)", "Smoke test (5 VUs, 2 min) — rapide, detecte les regressions majeures sans bloquer le pipeline", "Stress test pour trouver les limites", "Soak test pendant 8h"], answer: 1, explanation: "Le smoke test (2 min) est assez rapide pour le CI. Il detecte les regressions majeures (endpoint casse, erreur 500). Le load test complet est reserve au nightly ou pre-release." }
  ]},

  // ===== 12 — Architecture pratique =====
  { file: "quiz-12-01-documentation-architecture.html", title: "Quiz — Documentation d'architecture (ADR, C4)", subtitle: "Module 12 — Architecture pratique (Cours 77)", questions: [
    { label: "ADR", text: "Quand faut-il ecrire un ADR ?", options: ["Pour chaque decision de nommage de variable", "Pour les choix de technologie, patterns ou decisions irreversibles/couteuses a changer", "Uniquement quand le manager le demande", "Pour documenter chaque bug corrige"], answer: 1, explanation: "Un ADR documente les decisions architecturales significatives : choix de DB, pattern d'auth, CQRS vs CRUD. Pas pour les conventions locales ou les choix reversibles en 5 minutes." },
    { label: "C4 niveaux", text: "Quels sont les 4 niveaux du modele C4 ?", options: ["Frontend, Backend, Database, Cache", "Context (vue externe), Container (grands blocs), Component (modules internes), Code (classes)", "Dev, Staging, Preprod, Production", "Unit, Integration, E2E, Performance"], answer: 1, explanation: "C4 = 4 niveaux de zoom. Context (acteurs, systemes externes), Container (front, back, DB), Component (modules d'un container), Code (classes — rarement necessaire)." },
    { label: "Doc vivante", text: "Pourquoi la documentation-as-product est-elle superieure a un doc Word sur un drive ?", options: ["Elle est plus jolie", "Markdown dans le repo, PR obligatoire, CI-validated, evolue avec le code — jamais de doc orpheline", "Elle est plus facile a imprimer", "Elle est obligatoire par la loi"], answer: 1, explanation: "La doc vivante est dans le repo (decouvrable), mise a jour dans la meme PR que le code, validee en CI (fitness functions), et jamais desynchronisee." },
    { label: "3 audiences", text: "Quelles sont les 3 audiences de la documentation three-audience ?", options: ["Developpeurs junior, senior et lead", "AI agents (.context/), developpeurs (docs/dev/), non-techniques (docs/product/)", "Frontend, backend, devops", "Interne, client, partenaire"], answer: 1, explanation: "Chaque audience a des besoins differents. Les AI agents ont besoin de structure, les devs de guides techniques, les non-tech de getting started. Pas de duplication entre les sources." },
    { label: "Fitness doc", text: "A quoi servent les fitness functions pour la documentation ?", options: ["A generer la doc automatiquement", "A verifier en CI que les ADRs ont un status valide, que la doc n'est pas trop ancienne, et que le format est correct", "A traduire la doc en plusieurs langues", "A mesurer la satisfaction des lecteurs"], answer: 1, explanation: "Les fitness functions documentaires verifient automatiquement : chaque ADR a un status valide, les fichiers .context ne sont pas stale (> 90j sans review), le format est coherent." }
  ]},
  { file: "quiz-12-02-architecture-review.html", title: "Quiz — Architecture Review", subtitle: "Module 12 — Architecture pratique (Cours 78)", questions: [
    { label: "Code vs Archi review", text: "Quelle est la difference entre code review et architecture review ?", options: ["Ce sont des synonymes a des echelles differentes", "La code review examine une PR (style, bugs), l'architecture review examine le systeme entier (trade-offs, couplage, scalabilite)", "L'architecture review est pour les managers", "La code review est plus importante"], answer: 1, explanation: "Code review = une PR (15-30min). Architecture review = systeme entier (1-4h) avec trade-offs, couplage, scalabilite. Une brique parfaite au mauvais endroit est pire qu'une brique imparfaite au bon endroit." },
    { label: "ATAM", text: "Que permet la methode ATAM ?", options: ["Automatiser les tests d'architecture", "Analyser les trade-offs architecturaux en identifiant les quality attributes, scenarios critiques et risques", "Generer le code a partir de diagrammes", "Mesurer les performances du systeme"], answer: 1, explanation: "ATAM (Architecture Tradeoff Analysis Method) : presenter l'archi, identifier les quality attributes (perf, secu, maintenabilite), analyser les scenarios critiques, documenter les trade-offs et risques." },
    { label: "Fitness functions", text: "Qu'est-ce qu'une fitness function architecturale ?", options: ["Un test de performance physique", "Un test automatise verifiant un invariant architectural (pas de circular deps, bundle < 200KB, domaine isole)", "Un benchmark de framework", "Un test de charge k6"], answer: 1, explanation: "Les fitness functions protegent les decisions d'architecture contre l'erosion. Si quelqu'un importe TypeORM dans le domaine ou cree une dependance circulaire, le CI echoue." },
    { label: "LADR", text: "Qu'est-ce qu'un LADR en pull request ?", options: ["Un outil d'analyse de code", "Un Lightweight ADR directement dans la PR : context, decision, trade-off — le reviewer valide", "Un label GitHub", "Un type de commentaire automatique"], answer: 1, explanation: "Le LADR documente une decision architecturale legere dans la PR elle-meme. Le reviewer peut valider le trade-off avant le merge. Plus leger qu'un ADR complet." },
    { label: "Checklist", text: "Quels domaines couvre la checklist d'architecture review ?", options: ["Uniquement la performance", "Separation of concerns, scalability, resilience, security, observability, testability", "Uniquement la securite et les tests", "Le design UI et l'experience utilisateur"], answer: 1, explanation: "La checklist couvre 6 domaines : SoC (couplage, deps circulaires), scalabilite (stateless, bottlenecks), resilience (circuit breakers), securite (STRIDE), observabilite (SLOs), testabilite (pyramide)." }
  ]},
  { file: "quiz-12-03-dette-technique.html", title: "Quiz — Dette technique & Refactoring", subtitle: "Module 12 — Architecture pratique (Cours 79)", questions: [
    { label: "Quadrant Fowler", text: "Quel type de dette technique est le plus dangereux ?", options: ["Deliberee et prudente", "Accidentelle et imprudente — causee par l'ignorance, sans plan de remboursement", "Deliberee et imprudente", "Accidentelle et prudente"], answer: 1, explanation: "La dette accidentelle+imprudente vient du manque de connaissances ('c'est quoi une archi hexagonale ?'). Pas de plan de remboursement car l'equipe ne sait meme pas qu'elle s'endette." },
    { label: "Matrice impact/effort", text: "Quelle categorie de dette rembourser en priorite ?", options: ["Strategic (impact eleve, effort eleve)", "Quick Wins — impact eleve, effort faible : faire tout de suite", "Fill (impact faible, effort faible)", "Money Pit (impact faible, effort eleve)"], answer: 1, explanation: "Quick Wins (impact eleve, effort faible) d'abord. Puis Strategic (planifier). Ignorer les Fill. EVITER les Money Pits (effort eleve pour peu d'impact)." },
    { label: "Boy Scout Rule", text: "Qu'est-ce que la Boy Scout Rule en refactoring ?", options: ["Toujours refactorer un module entier dans chaque PR", "Laisser le code plus propre qu'on ne l'a trouve — renommer une variable, supprimer du code mort, dans chaque PR", "Ne jamais toucher au code existant", "Ecrire un ADR pour chaque modification"], answer: 1, explanation: "Le refactoring tactique (Boy Scout) se fait dans chaque PR : renommer une variable peu claire, supprimer du code mort, ajouter un type manquant. Le refactoring strategique est une PR dediee." },
    { label: "Quand NE PAS refactorer", text: "Quand ne faut-il PAS rembourser la dette technique ?", options: ["Jamais, il faut toujours refactorer", "Si le module sera supprime bientot, si le cout du refactoring depasse la dette sur 6 mois, ou si le code n'est jamais touche", "Si l'equipe est trop petite", "Si le product owner n'est pas d'accord"], answer: 1, explanation: "'Working code that nobody touches has zero maintenance cost.' Refactorer du code legacy en fin de vie ou jamais modifie gaspille du temps. Le rapport cout/benefice doit etre positif." },
    { label: "Mesurer", text: "Comment mesurer la dette technique ?", options: ["Uniquement avec le code coverage", "Cyclomatic complexity, duplication, coupling, test coverage des branches critiques, time to change", "Le nombre de lignes de code", "Le nombre de fichiers dans le projet"], answer: 1, explanation: "Metriques multiples : complexite cyclomatique > 10 (alerte), duplication > 5%, couplage instable > 0.8, coverage branches < 70%, et le time to change (> 2h pour un changement simple)." }
  ]},
  { file: "quiz-12-04-strategies-migration.html", title: "Quiz — Strategies de migration", subtitle: "Module 12 — Architecture pratique (Cours 80)", questions: [
    { label: "3 strategies", text: "Pourquoi le Strangler Fig est-il prefere au Big Bang pour les migrations ?", options: ["Il est plus rapide", "Le risque est reparti sur chaque feature migree — un echec n'impacte qu'une partie, pas tout le systeme", "Il ne necessite pas de proxy", "Il est moins cher en infrastructure"], answer: 1, explanation: "Le Strangler Fig migre feature par feature derriere un proxy. Chaque feature est testee et validee. Le Big Bang concentre tout le risque en un seul moment et echoue 70-80% du temps." },
    { label: "Pre-flight report", text: "Pourquoi generer un pre-flight diff report AVANT de migrer ?", options: ["Pour impressionner le management", "Pour inventorier le contenu, detecter les pages non-migrables automatiquement, les broken links, et estimer le travail", "Pour generer la documentation du nouveau systeme", "Pour tester les performances"], answer: 1, explanation: "Le pre-flight identifie les 5% de contenu necessitant une review manuelle, les 842 URLs a rediriger, les 23 broken links. Pas de surprise pendant la migration." },
    { label: "AI conversion", text: "Quel est le taux de conversion automatique typique du HTML legacy vers des blocks structures ?", options: ["100% — tout est automatisable", "~95% automatique, 5% necessitent une review manuelle (HTML custom complexe)", "50% au mieux", "L'IA ne peut pas convertir du HTML"], answer: 1, explanation: "L'IA convertit ~95% du HTML standard en blocks structures. Les 5% restants (custom scripts, iframes, CSS complexe inline) necessitent une review manuelle. L'IA accelere massivement." },
    { label: "Data migration", text: "Quel pattern de migration de donnees combine copie initiale et synchronisation temps reel ?", options: ["ETL batch uniquement", "Backfill + CDC — copier l'existant puis streamer les deltas en temps reel", "Dual-write exclusivement", "Import/export CSV"], answer: 1, explanation: "Backfill copie les donnees existantes. CDC (Change Data Capture) stream ensuite les changements en temps reel. Combine, cela garantit une migration complete sans perte de donnees recentes." },
    { label: "Redirect 301 vs 302", text: "Pourquoi utiliser 301 plutot que 302 pour les redirections de migration finalisees ?", options: ["Le 301 est plus rapide", "Le 301 transfere le 'link juice' SEO vers la nouvelle URL, le 302 ne le fait pas", "Le 302 est deprecie", "Il n'y a pas de difference"], answer: 1, explanation: "Le 301 (permanent) transfere le SEO vers la nouvelle URL. Le 302 (temporaire) est pour la migration en cours (destination pas encore definitive). Une fois finalise, toujours 301." }
  ]},
  { file: "quiz-12-05-plugin-extension-architecture.html", title: "Quiz — Plugin & Extension Architecture", subtitle: "Module 12 — Architecture pratique (Cours 81)", questions: [
    { label: "Manifest", text: "Pourquoi le manifest de plugin est-il declaratif ?", options: ["Pour faciliter la lecture par les humains", "Pour que le systeme puisse valider et restreindre les capacites du plugin AVANT activation (moindre privilege)", "Pour standardiser le format YAML", "Pour accelerer le chargement du plugin"], answer: 1, explanation: "Le manifest declare permissions, endpoints, events, egress hosts. Le systeme valide tout avant activation. Le plugin ne peut pas faire plus que ce que le manifest declare — principe du moindre privilege." },
    { label: "Adapter boundary", text: "Quel est l'avantage de l'adapter boundary pattern pour les editeurs tiers ?", options: ["Il accelere les editeurs", "On place une interface entre l'app et le service tiers — si on remplace le service, on change 1 adapter au lieu de tout refactorer", "Il est requis par les editeurs", "Il ameliore la securite"], answer: 1, explanation: "L'adapter boundary isole les dependances externes. L'app ne connait que l'interface (port). L'adapter implemente pour Unlayer, Elasticsearch, etc. Remplacement = 1 adapter, pas tout le code." },
    { label: "Block variants", text: "A quoi sert un systeme de block variants pour les plugins ?", options: ["A versionner le code du plugin", "A permettre aux plugins de proposer des variantes de rendu pour les blocs du CMS (ex: hero avec video vs image)", "A bloquer les plugins non autorises", "A compresser le code des blocs"], answer: 1, explanation: "Un plugin peut enregistrer des variantes de blocs existants (hero-video, hero-carousel) sans modifier le code du CMS. Le systeme de blocs est extensible par design." },
    { label: "Health check plugin", text: "Que se passe-t-il si un plugin echoue 3 health checks consecutifs ?", options: ["Rien, on log seulement", "Le plugin est automatiquement desactive et l'admin est notifie — protection du systeme principal", "Le serveur entier s'arrete", "Le plugin est mis a jour automatiquement"], answer: 1, explanation: "3 echecs consecutifs = auto-disable. Le systeme principal est protege contre un plugin defaillant. L'admin recoit une notification pour investiguer et reactiver si necessaire." },
    { label: "Route mount blocks", text: "Qu'est-ce que le route mounting pour les plugins ?", options: ["Monter un disque dur pour le plugin", "Le plugin declare des routes dans son manifest que le systeme monte automatiquement dans le routeur principal", "Redirecter les requetes vers le plugin", "Bloquer les routes du plugin"], answer: 1, explanation: "Le manifest declare les routes (ex: /recommendations). Le systeme les monte dans le routeur avec les middlewares de securite. Le plugin ne peut pas monter de routes non declarees." }
  ]},
  { file: "quiz-12-06-conway-team-topologies.html", title: "Quiz — Conway's Law & Team Topologies", subtitle: "Module 12 — Architecture pratique (Cours 82)", questions: [
    { label: "Conway's Law", text: "Que dit Conway's Law sur la relation entre organisation et architecture ?", options: ["Les meilleures equipes produisent la meilleure architecture", "La structure de communication de l'organisation se retrouve dans l'architecture du systeme", "L'architecture determine l'organisation", "Il n'y a pas de lien entre organisation et architecture"], answer: 1, explanation: "3 equipes (front, back, DBA) = architecture en 3 couches. 3 equipes domaine (catalog, orders, users) = 3 services. L'architecture est une copie des structures de communication." },
    { label: "Inverse Conway", text: "Qu'est-ce que l'Inverse Conway Maneuver ?", options: ["Ignorer Conway's Law", "Definir l'architecture cible d'abord, puis reorganiser les equipes pour correspondre", "Laisser l'organisation dicter l'architecture", "Reorganiser les equipes tous les trimestres"], answer: 1, explanation: "Au lieu de subir Conway's Law, on l'exploite : definir l'architecture souhaitee (microservices par domaine), puis organiser les equipes en consequence (equipe Catalog, equipe Orders)." },
    { label: "4 types d'equipes", text: "Quels sont les 4 types d'equipes Team Topologies ?", options: ["Dev, QA, Ops, Management", "Stream-aligned (valeur business), Platform (outils), Enabling (coaching), Complicated-subsystem (expertise technique)", "Frontend, Backend, DevOps, Data", "Junior, Senior, Lead, Architect"], answer: 1, explanation: "Stream-aligned delivre de la valeur. Platform fournit les outils (CI/CD). Enabling aide a monter en competence (pas de code en prod). Complicated-subsystem gere le complexe (ML, securite)." },
    { label: "Cognitive load", text: "Pourquoi la charge cognitive est-elle un facteur cle dans Team Topologies ?", options: ["Pour reduire le stress des developpeurs", "Une equipe qui gere trop de systemes/domaines devient inefficace — limiter la charge cognitive maximise la productivite", "Pour justifier l'embauche de plus de developpeurs", "Pour mesurer la complexite du code"], answer: 1, explanation: "Si une equipe de 6 gere 15 microservices, elle ne peut pas les maitriser tous. Limiter la charge cognitive (5-7 services max) permet a l'equipe de comprendre, maintenir et faire evoluer efficacement." },
    { label: "Communication", text: "Comment communiquer une decision architecturale a des audiences differentes ?", options: ["Le meme ADR pour tout le monde", "Adapter le message : CTO (business impact, couts), devs (details techniques, trade-offs), PO (features impactees, timeline)", "Ne communiquer qu'aux developpeurs", "Un email unique a toute l'entreprise"], answer: 1, explanation: "Le CTO veut savoir l'impact business et les couts. Les devs veulent les details techniques et trade-offs. Le PO veut savoir quelles features sont impactees et le calendrier. Adapter le message a l'audience." }
  ]},
  { file: "quiz-12-07-evolutionary-finops-wardley.html", title: "Quiz — Evolutionary Architecture, FinOps & Wardley", subtitle: "Module 12 — Architecture pratique (Cours 83)", questions: [
    { label: "Evolutionary", text: "Qu'est-ce qui distingue une architecture evolutive d'une architecture traditionnelle ?", options: ["Elle utilise des technologies plus recentes", "Elle accueille le changement via un feedback loop continu (construire -> mesurer via fitness functions -> adapter)", "Elle est plus simple", "Elle ne necessite pas de documentation"], answer: 1, explanation: "L'architecture traditionnelle planifie tout puis ne touche plus. L'evolutive construit, mesure via fitness functions, adapte, et repete. Les fitness functions guident l'evolution en continu." },
    { label: "Build vs Buy", text: "Comment decider entre build et buy pour un composant ?", options: ["Toujours build pour garder le controle", "Build si avantage concurrentiel et expertise interne, Buy si commodity (auth, email, hosting) et time-to-market urgent", "Toujours buy pour aller plus vite", "La decision depend uniquement du cout"], answer: 1, explanation: "Le Wardley Map aide : composants en genesis/custom = build (differenciateur). Composants en commodity = buy (auth/Keycloak, hosting/AWS). Build ce qui vous differencie, buy le reste." },
    { label: "FinOps", text: "Quel est le principe fondamental du FinOps ?", options: ["Reduire les couts cloud au maximum", "Optimiser le rapport valeur/cout du cloud — chaque equipe est responsable de ses depenses et peut les mesurer", "Utiliser uniquement des services gratuits", "Centraliser toutes les depenses dans un seul budget"], answer: 1, explanation: "Le FinOps n'est pas 'depenser moins' mais 'depenser mieux'. Chaque equipe voit et comprend ses couts cloud, prend des decisions informees, et optimise le rapport valeur delivree / cout." },
    { label: "Wardley Map", text: "A quoi sert un Wardley Map ?", options: ["A documenter l'architecture technique", "A visualiser les composants sur un axe evolution (genesis -> commodity) pour guider les decisions strategiques (build/buy, investissement)", "A planifier les sprints", "A mesurer les performances"], answer: 1, explanation: "Le Wardley Map positionne chaque composant selon sa maturite (genesis, custom, product, commodity). Un composant en genesis merite de l'investissement, un commodity doit etre achete." },
    { label: "Guided change", text: "Comment les fitness functions guident-elles l'evolution de l'architecture ?", options: ["Elles generent automatiquement le code", "Elles definissent des invariants mesurables (bundle < 200KB, pas de circular deps) qui alertent si une evolution viole les contraintes", "Elles empechent tout changement", "Elles documentent les changements passes"], answer: 1, explanation: "Les fitness functions sont des gardes-fous automatises. L'architecture peut evoluer tant que les invariants sont respectes. Si un changement viole un invariant, le CI bloque et l'equipe decide." }
  ]},

  // ===== 13 — Culture architecturale =====
  { file: "quiz-13-01-architecture-mobile.html", title: "Quiz — Architecture mobile", subtitle: "Module 13 — Culture architecturale (Cours 84)", questions: [
    { label: "Offline-first", text: "Pourquoi l'offline-first est-il obligatoire en mobile ?", options: ["Pour reduire les couts de bande passante", "Le reseau mobile est intermittent (metro, avion, campagne) — l'app doit fonctionner sans connexion", "Pour accelerer les animations", "Pour respecter les guidelines App Store"], answer: 1, explanation: "Le mobile est en territoire hostile : reseau intermittent, tunnels, zones blanches. Les operations doivent s'executer localement d'abord, puis se synchroniser quand le reseau revient." },
    { label: "Delta sync", text: "Pourquoi le delta sync est-il critique en mobile ?", options: ["Pour simplifier le code", "Au lieu de telecharger toutes les donnees a chaque ouverture (~20MB), ne recuperer que les elements modifies depuis le dernier sync (~100KB)", "Pour eviter les conflits", "Pour respecter le RGPD"], answer: 1, explanation: "GET /products?since=timestamp ne recupere que les modifications. Economise bande passante, batterie et temps de chargement — des ressources critiques en mobile." },
    { label: "Cross-platform", text: "Quel est l'avantage principal de React Native pour une equipe web existante ?", options: ["Les performances sont superieures au natif", "L'equipe JS/TS existante peut partager du code avec le web et developper pour iOS + Android avec une seule codebase", "React Native ne necessite pas de Mac pour developper iOS", "Les apps React Native sont plus petites"], answer: 1, explanation: "React Native permet a une equipe JS/TS de developper iOS + Android avec une codebase. Le partage de code avec l'app web React existante est un gain significatif." },
    { label: "App Store", text: "Quel probleme specifique au mobile n'existe pas en web ?", options: ["Les problemes de SEO", "Plusieurs versions de l'app coexistent en production car les utilisateurs ne mettent pas tous a jour en meme temps", "Les problemes de responsive design", "La gestion des cookies"], answer: 1, explanation: "En web, tout le monde voit la derniere version. En mobile, certains restent sur v1 pendant que v3 est deployee. L'API doit supporter plusieurs versions simultanement." },
    { label: "Mutation queue", text: "A quoi sert la mutation queue dans une architecture mobile offline-first ?", options: ["A trier les notifications", "A mettre en file d'attente les modifications effectuees hors ligne pour les synchroniser quand le reseau revient", "A compresser les donnees", "A gerer les permissions"], answer: 1, explanation: "L'utilisateur modifie des donnees hors ligne. Les mutations sont stockees dans une queue locale. Quand le reseau revient, la queue se vide en envoyant chaque mutation au serveur, avec resolution de conflits." }
  ]},
  { file: "quiz-13-02-mlops-ai-systems.html", title: "Quiz — MLOps & AI Systems", subtitle: "Module 13 — Culture architecturale (Cours 85)", questions: [
    { label: "Feature Store", text: "Quel probleme le Feature Store resout-il ?", options: ["Le stockage des modeles ML", "Le training/serving skew — les features doivent etre calculees de maniere identique en training (offline) et en serving (online)", "La compression des donnees d'entrainement", "Le versioning du code Python"], answer: 1, explanation: "Sans Feature Store, les features calculees en training (Pandas batch) peuvent differer de celles en serving (temps reel). Le skew cause des predictions fausses. Le Feature Store definit les features une seule fois." },
    { label: "Champion/Challenger", text: "Comment fonctionne le A/B testing ML champion/challenger ?", options: ["On compare les modeles sur un jeu de test statique", "Le champion (modele actuel) recoit 90% du trafic, le challenger (nouveau) 10% — on compare les metriques business", "On choisit le modele le plus recent", "On demande aux utilisateurs de voter"], answer: 1, explanation: "Comme le canary deployment, le champion recoit le gros du trafic. Le challenger est teste sur 10%. On compare click-through, conversion, revenue. Meilleur -> promote. Pire -> rollback." },
    { label: "Data drift", text: "Qu'est-ce que le data drift et pourquoi est-il dangereux ?", options: ["Un bug dans le pipeline de donnees", "La distribution des donnees en production change par rapport a celle d'entrainement — le modele fait des predictions de moins en moins fiables", "Un changement de schema de la base de donnees", "Une perte de donnees en transit"], answer: 1, explanation: "Un modele entraine sur les donnees 2024 peut devenir obsolete en 2025 si les comportements utilisateurs changent. Le monitoring de drift detecte ces ecarts et declenche un re-entrainement." },
    { label: "EU AI Act", text: "Quelle exigence l'EU AI Act impose-t-il pour les systemes IA a haut risque ?", options: ["Utiliser uniquement des modeles open-source", "Un risk register, un audit trail des decisions, et l'explainability (pouvoir justifier chaque decision de l'IA)", "Limiter les modeles a 1 milliard de parametres", "Heberger les modeles uniquement en Europe"], answer: 1, explanation: "L'EU AI Act exige pour les systemes a haut risque : un registre des risques, la tracabilite des decisions (audit trail), et la capacite a expliquer pourquoi l'IA a pris telle decision." },
    { label: "Model registry", text: "A quoi sert un model registry comme MLflow ?", options: ["A entrainer les modeles plus rapidement", "A versionner les modeles, leurs metriques et metadonnees pour permettre le rollback et la reproductibilite", "A deployer les modeles en production", "A generer les features automatiquement"], answer: 1, explanation: "Le model registry stocke chaque version du modele avec ses metriques (accuracy, precision), ses hyperparametres, et ses dependances. Le rollback vers une version precedente est trivial." }
  ]},
  { file: "quiz-13-03-blockchain-consensus.html", title: "Quiz — Blockchain & Consensus distribue", subtitle: "Module 13 — Culture architecturale (Cours 86)", questions: [
    { label: "Quand blockchain", text: "Dans quel cas la blockchain fait-elle reellement sens ?", options: ["Pour toute application necessitant une base de donnees", "Quand il n'y a pas de tiers de confiance entre les parties et qu'on a besoin de tracabilite immutable", "Pour ameliorer les performances", "Pour remplacer les bases de donnees relationnelles"], answer: 1, explanation: "La blockchain fait sens quand : pas de tiers de confiance, besoin de tracabilite immutable, tokens/actifs numeriques. Dans 99% des cas (tu as un serveur), une DB suffit." },
    { label: "PoW vs PoS", text: "Pourquoi Ethereum est-il passe du Proof of Work au Proof of Stake ?", options: ["Pour augmenter le nombre de transactions", "Le PoW consomme enormement d'energie (calculs inutiles), le PoS selectionne les validateurs selon leur mise en jeu — 99.95% moins d'energie", "Pour reduire le prix des transactions", "Pour rendre le reseau plus decentralise"], answer: 1, explanation: "Le PoW exige des calculs massifs (minage) consommant autant qu'un pays. Le PoS selectionne les validateurs proportionnellement a leur ETH mis en jeu — meme securite, 99.95% moins d'energie." },
    { label: "Smart contracts", text: "Quel est le principal risque des smart contracts ?", options: ["Ils sont trop lents", "Le code est immutable — un bug est permanent et ne peut pas etre corrige (cf. le hack The DAO : $60M)", "Ils coutent trop cher a deployer", "Ils ne supportent pas le JavaScript"], answer: 1, explanation: "Un smart contract deploye sur la blockchain est immutable. Un bug de reentrancy dans The DAO a permis de voler $60M sans possibilite de correction. L'audit du code est critique." },
    { label: "Quand PAS blockchain", text: "Pourquoi la blockchain est-elle inutile quand tu controles le systeme ?", options: ["Elle est toujours utile comme backup", "Si tu as un serveur central de confiance, une base de donnees est plus rapide, moins chere et plus simple — la blockchain ajoute de la complexite sans valeur", "La blockchain ne fonctionne pas avec des serveurs", "Elle est interdite pour les entreprises"], answer: 1, explanation: "La blockchain resout le probleme de confiance entre parties qui ne se font pas confiance. Si tu controles le systeme, une DB classique est plus performante, moins chere et plus simple." },
    { label: "IPFS", text: "Quel est le role d'IPFS dans l'ecosysteme Web3 ?", options: ["Remplacer HTTP completement", "Stockage de fichiers decentralise content-addressed — le hash du fichier EST son adresse, garantissant l'integrite", "Executer les smart contracts", "Gerer les transactions blockchain"], answer: 1, explanation: "IPFS (InterPlanetary File System) stocke les fichiers de maniere decentralisee. L'adresse est le hash du contenu — si le fichier change, l'adresse change. Immutabilite et integrite par design." }
  ]},
  { file: "quiz-13-04-iot-edge.html", title: "Quiz — IoT & Edge Architecture", subtitle: "Module 13 — Culture architecturale (Cours 87)", questions: [
    { label: "Contraintes IoT", text: "Quelle est la contrainte principale des devices IoT ?", options: ["Le prix de fabrication", "Ressources extremement limitees : CPU 80-240MHz, RAM 1-512KB, batterie 2-10 ans, reseau intermittent", "La taille physique du device", "La compatibilite avec les navigateurs web"], answer: 1, explanation: "Les devices IoT ont des ressources minimales : pas de frameworks lourds, pas de crypto complexe, pas de connexion permanente. Le code doit etre minimal et econome en energie." },
    { label: "Edge processing", text: "Pourquoi l'edge gateway reduit-il 99%+ du trafic reseau ?", options: ["Il compresse les donnees", "Il agrege localement les mesures (moyenne sur 15min) au lieu d'envoyer chaque mesure brute au cloud", "Il filtre les doublons", "Il reduit la frequence des capteurs"], answer: 1, explanation: "50 capteurs a 1/s = 4.3M messages/jour. L'edge agrege (moyenne 15min) et envoie ~4,800 messages/jour. Les alertes urgentes sont traitees localement sans attendre le cloud." },
    { label: "MQTT QoS", text: "Quel niveau de QoS MQTT choisir pour les alertes critiques IoT ?", options: ["QoS 0 (at-most-once) pour la vitesse", "QoS 1 (at-least-once) — garantie de livraison avec possibles doublons, bon compromis", "QoS 2 (exactly-once) dans tous les cas", "MQTT ne supporte pas les niveaux de QoS"], answer: 1, explanation: "QoS 0 = fire-and-forget (telemetrie frequente). QoS 1 = at-least-once avec ACK (alertes). QoS 2 = exactly-once mais lent (operations critiques). Pour les alertes, QoS 1 est le bon compromis." },
    { label: "Time-series DB", text: "Pourquoi utiliser une base time-series (InfluxDB, TimescaleDB) pour les donnees IoT ?", options: ["Elles sont moins cheres", "Elles sont optimisees pour l'ingestion massive de points horodates, la compression temporelle, et les requetes par plage de temps", "Elles supportent les transactions ACID", "Elles remplacent PostgreSQL pour tout"], answer: 1, explanation: "Les bases time-series compressent les donnees temporelles (delta encoding), supportent l'ingestion massive (millions de points/sec), et optimisent les requetes par plage de temps et agregation." },
    { label: "OTA updates", text: "Pourquoi les mises a jour OTA (Over-The-Air) sont-elles critiques pour la securite IoT ?", options: ["Pour ajouter de nouvelles fonctionnalites", "Les devices deployes ne peuvent pas etre rappeles physiquement — les vulnerabilites firmware doivent etre corrigees a distance", "Pour reduire les couts de maintenance", "Pour mettre a jour l'interface utilisateur"], answer: 1, explanation: "Un capteur deploye dans un champ ne peut pas etre rappele en usine. Si une vulnerabilite est decouverte, l'OTA est le seul moyen de corriger. Sans OTA, le device reste vulnerable indefiniment." }
  ]},
  { file: "quiz-13-05-crdt-collaboration.html", title: "Quiz — CRDT & Collaboration temps reel", subtitle: "Module 13 — Culture architecturale (Cours 88)", questions: [
    { label: "OT vs CRDT", text: "Quelle est la difference fondamentale entre OT et CRDT ?", options: ["OT est plus recent que CRDT", "OT utilise un serveur central pour transformer les operations, CRDT garantit la convergence mathematiquement sans serveur central", "CRDT est pour le texte, OT pour les images", "Il n'y a pas de difference pratique"], answer: 1, explanation: "OT (Google Docs) : un serveur central transforme les operations concurrentes. CRDT (Figma, Yjs) : les operations commutent mathematiquement — convergence garantie sans coordinateur central, fonctionne offline." },
    { label: "G-Counter", text: "Comment fonctionne un G-Counter CRDT ?", options: ["Un compteur global partage entre tous les noeuds", "Chaque noeud a son propre compteur, le total = somme de tous, le merge = max de chaque noeud", "Un compteur centralisé avec un lock distribue", "Un compteur qui ne peut que decrementer"], answer: 1, explanation: "Le G-Counter (Grow-only) : chaque noeud incremente son compteur local. Le total est la somme. Le merge prend le max par noeud — convergence garantie peu importe l'ordre des merges." },
    { label: "Yjs", text: "Pourquoi Yjs est-il prefere pour l'edition collaborative en production ?", options: ["Il est plus simple a comprendre", "Il offre des CRDT optimises pour le texte et les structures de donnees complexes, avec support offline natif et integration framework", "Il est le seul a supporter le JavaScript", "Il est gratuit contrairement aux alternatives"], answer: 1, explanation: "Yjs fournit des CRDT optimises (Y.Text, Y.Array, Y.Map), fonctionne offline nativement, s'integre avec React/Vue, et a un ecosysteme mature (awareness, persistence, transport)." },
    { label: "Convergence", text: "Pourquoi la convergence est-elle le probleme central de l'edition collaborative ?", options: ["Pour des raisons de performance", "Deux utilisateurs editant simultanement doivent aboutir au MEME document final, peu importe l'ordre de reception des operations", "Pour eviter les conflits de merge git", "Pour respecter les droits d'auteur"], answer: 1, explanation: "Si Alice insere '!' et Bob insere ' World' au meme endroit, le resultat doit etre identique chez les deux ('Hello World!' ou 'Hello! World'). Sans convergence = corruption du document." },
    { label: "Awareness", text: "A quoi sert le protocole d'awareness dans la collaboration temps reel ?", options: ["A detecter les conflits de fusion", "A afficher les curseurs et selections des autres utilisateurs en temps reel (presence)", "A compresser les donnees echangees", "A authentifier les collaborateurs"], answer: 1, explanation: "L'awareness montre qui est connecte, ou est leur curseur, ce qu'ils selectionnent. C'est essentiel pour l'UX collaborative — les utilisateurs voient ou les autres travaillent en temps reel." }
  ]},
  { file: "quiz-13-06-modernisation-legacy.html", title: "Quiz — Modernisation Legacy & ACL", subtitle: "Module 13 — Culture architecturale (Cours 89)", questions: [
    { label: "ACL", text: "Quel est le role de l'Anti-Corruption Layer (ACL) ?", options: ["Proteger contre les virus informatiques", "Empecher les concepts et modeles du systeme legacy de contaminer le nouveau systeme — un mur coupe-feu entre les deux", "Corrompre intentionnellement les donnees du legacy", "Authentifier les appels entre systemes"], answer: 1, explanation: "L'ACL traduit entre les modeles du legacy et du nouveau systeme. Le nouveau systeme ne voit jamais les concepts legacy directement. Si le legacy utilise des codes numeriques, l'ACL les traduit en enums propres." },
    { label: "Pourquoi pas Big Bang", text: "Pourquoi ne pas tout refaire (Big Bang) pour un systeme legacy ?", options: ["C'est interdit par la loi", "Le code legacy contient des annees de regles metier implicites, les edge cases sont geres par du code que personne ne comprend, et le business ne peut pas s'arreter", "Il suffit de bien documenter le legacy avant", "Le Big Bang est toujours la meilleure approche"], answer: 1, explanation: "Le legacy contient des annees de regles metier implicites. Le Big Bang echoue 70-80% du temps (Gartner) car les specs sont incompletes et le business ne peut pas s'arreter." },
    { label: "Cohabitation", text: "Pourquoi la cohabitation legacy/nouveau est-elle necessaire ?", options: ["Pour comparer les performances", "Les deux systemes doivent fonctionner en parallele pendant la migration incrementale — le legacy reste operationnel tant que le nouveau n'est pas 100% pret", "Pour des raisons legales", "Pour faire plaisir aux utilisateurs du legacy"], answer: 1, explanation: "La migration incrementale (Strangler Fig) implique que les deux systemes coexistent. Le proxy route vers l'un ou l'autre. Le legacy n'est decommissionne que quand le nouveau est 100% operationnel et valide." },
    { label: "Integration patterns", text: "Quel pattern d'integration est le plus sûr pour connecter le nouveau systeme au legacy ?", options: ["Appels directs a la base de donnees du legacy", "Un API facade ou event bridge qui traduit entre les deux systemes, evitant le couplage direct a la DB legacy", "Partager la meme base de donnees", "Copier-coller le code du legacy"], answer: 1, explanation: "Acceder directement a la DB du legacy cree un couplage fort et dangereux. Un API facade ou event bridge isole les systemes. Le legacy peut changer son schema sans casser le nouveau." },
    { label: "Regles metier implicites", text: "Pourquoi les regles metier implicites du legacy sont-elles le plus grand risque d'une migration ?", options: ["Elles ralentissent le systeme", "Elles ne sont documentees nulle part et ne se revelent que quand un edge case survient en production sur le nouveau systeme", "Elles sont faciles a reproduire", "Elles n'existent pas vraiment"], answer: 1, explanation: "Un if/else ajoute il y a 8 ans pour un client specifique, un arrondi fiscal dans une stored procedure, un tri special pour un pays... Ces regles ne sont dans aucune spec et se revelent par des bugs en production." }
  ]},
];

let count = 0;
for (const quiz of quizzes) {
  const html = template(quiz.title, quiz.subtitle, quiz.questions);
  fs.writeFileSync(path.join(dir, quiz.file), html);
  count++;
  console.log(`Created: ${quiz.file}`);
}
console.log(`\nTotal: ${count} quiz files generated.`);
